import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.PublicKey;
import java.security.PrivateKey;
import java.security.SecureRandom;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;

import javax.crypto.Cipher;

public class MyAuthentication {

    /**
     * Client Private Key
     */
    private static final String CLIENT_PRIV_KEY = "";
    
    /**
     * Client Public Key
     */
    private static final String CLIENT_PUBLIC_KEY = "";

    public static void main(String[] args) throws Exception {
        KeyPairGenerator keyPairGen = KeyPairGenerator.getInstance("RSA");

        keyPairGen.initialize(2048);
        KeyPair clientKeyPair = keyPairGen.generateKeyPair();
        PrivateKey clientPrivateKey = clientKeyPair.getPrivate();
        PublicKey clientPublicKey  = clientKeyPair.getPublic();
        System.out.println("ClientPrivateKey : " + bytesToHex(clientPrivateKey.getEncoded()));
        System.out.println("ClientPublicKey : " + bytesToHex(clientPublicKey.getEncoded()));

        byte[] randFromServer = generateRandomBytes(16);
        System.out.println("Server generated random data = " + bytesToHex(randFromServer));

        Cipher cipherEnc = Cipher.getInstance("RSA/ECB/PKCS1Padding");
        cipherEnc.init(Cipher.ENCRYPT_MODE, clientPrivateKey);
        byte[] encryptedByClientPriv = cipherEnc.doFinal(randFromServer);
        System.out.println("Client used PRIVATE key to encrypt -> " + bytesToHex(encryptedByClientPriv));

        Cipher cipherDec = Cipher.getInstance("RSA/ECB/PKCS1Padding");
        cipherDec.init(Cipher.DECRYPT_MODE, clientPublicKey);
        byte[] decryptedOnServer = cipherDec.doFinal(encryptedByClientPriv);
        System.out.println("Server used CLIENT's PUBLIC key to decrypt -> " + bytesToHex(decryptedOnServer));

        if (Arrays.equals(randFromServer, decryptedOnServer)) {
            System.out.println("Server verification PASSED! Client indeed holds the private key.");
        } else {
            System.out.println("Server verification FAILED!");
        }


    }

    private static byte[] generateRandomBytes(int length) throws NoSuchAlgorithmException {
        SecureRandom random = new SecureRandom();
        byte[] bytes = new byte[length];
        random.nextBytes(bytes);
        return bytes;
    }


    private static String bytesToHex(byte[] data) {
        StringBuilder sb = new StringBuilder();
        for (byte b : data) {
            sb.append(String.format("%02X", b));
        }
        return sb.toString();
    }
}
